package com.spaceagent.platform.inference;

import com.spaceagent.platform.inference.api.InferenceBudgetApplicationApi;import com.spaceagent.platform.inference.application.InferenceBudgetApplicationService;import com.spaceagent.platform.inference.infrastructure.memory.InMemoryInferenceBudgetRepository;import com.spaceagent.shared.exception.BusinessException;import com.spaceagent.shared.id.UuidGenerator;import org.junit.jupiter.api.Test;import java.time.Instant;import static org.assertj.core.api.Assertions.*;
class PlatformInferenceBudgetApplicationTest{
 @Test void reservesSettlesReleasesAndRetainsUnknownAgainstHardLimits(){var repo=new InMemoryInferenceBudgetRepository(()->Instant.parse("2026-08-23T19:00:00Z"));var api=new InferenceBudgetApplicationService(repo,new UuidGenerator(),()->Instant.parse("2026-08-23T19:00:00Z"));api.configure(new InferenceBudgetApplicationApi.ConfigurePolicyCommand("tenant","owner",true,2,100,100));var first=api.reserve(command("run-1","call-1",10,20));assertThat(api.usage("tenant").reservedRequests()).isEqualTo(1);api.settle(first.id(),7,3);var settled=api.usage("tenant");assertThat(settled.consumedRequests()).isEqualTo(1);assertThat(settled.consumedTokens()).isEqualTo(10);assertThat(settled.consumedCostMicros()).isEqualTo(10);var unknown=api.reserve(command("run-2","call-2",10,20));api.markUnknown(unknown.id());assertThat(api.usage("tenant").reservedRequests()).isEqualTo(1);assertThatThrownBy(()->api.reserve(command("run-3","call-3",1,1))).isInstanceOfSatisfying(BusinessException.class,e->assertThat(e.getCode()).isEqualTo("INFERENCE_REQUEST_QUOTA_EXCEEDED"));}
 @Test void enabledCostBudgetFailsClosedWithoutPrice(){var api=new InferenceBudgetApplicationService(new InMemoryInferenceBudgetRepository(Instant::now),new UuidGenerator(),Instant::now);api.configure(new InferenceBudgetApplicationApi.ConfigurePolicyCommand("tenant","owner",true,0,0,100));var c=new InferenceBudgetApplicationApi.ReserveCommand("tenant","run","call","provider","model",null,null,null,1,1);assertThatThrownBy(()->api.reserve(c)).isInstanceOfSatisfying(BusinessException.class,e->assertThat(e.getCode()).isEqualTo("INFERENCE_PRICE_REQUIRED"));}
 private static InferenceBudgetApplicationApi.ReserveCommand command(String run,String call,long in,long out){return new InferenceBudgetApplicationApi.ReserveCommand("tenant",run,call,"provider","model","price",1_000_000L,1_000_000L,in,out);}
}
